import { stepQuantity, id, newList, listRepository, recipeRepository, localShareService, addIngredients, sameProduct, compatibleUnits } from './domain.js';

const app = document.querySelector('#app');
const modal = document.querySelector('#modal');
const categories = ['Café da manhã', 'Almoço', 'Jantar', 'Lanches', 'Massas', 'Carnes', 'Sobremesas', 'Bebidas'];
const productCategories = ['Mercearia', 'Hortifruti', 'Açougue', 'Laticínios', 'Padaria', 'Temperos', 'Outros'];
let lists = [], recipes = [], storageError = false, recipeError = false, query = '', category = 'Todas';
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const icons = { home: '<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>', list: '<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 3h6v4H9zM9 12h6M9 16h6"/>', recipes: '<path d="M7 14a5 5 0 0 1-2-9 5 5 0 0 1 7-1 5 5 0 0 1 7 1 5 5 0 0 1-2 9v7H7zM7 17h10"/>', history: '<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6M12 7v6l4 2"/>', share: '<circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m9 11 6-4m-6 6 6 4"/>', plus: '<path d="M12 5v14M5 12h14"/>', clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>', people: '<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5"/>', arrow: '<path d="m9 5 7 7-7 7"/>', back: '<path d="m15 5-7 7 7 7"/>', search: '<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>', check: '<path d="m5 12 4 4L19 6"/>', trash: '<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>' };
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.list}</svg>`;
const qty = item => {
  const quantity = Number(item.quantity ?? 1);
  const unit = item.unit || 'unidade';
  const plurals = { unidade: 'unidades', dente: 'dentes', folha: 'folhas', pitada: 'pitadas', 'colher de sopa': 'colheres de sopa', 'colher de chá': 'colheres de chá' };
  return `${quantity.toLocaleString('pt-BR')} ${esc(quantity > 1 ? plurals[unit] || unit : unit)}`;
};
const active = () => lists.filter(list => list.status === 'ACTIVE');
function toast(message) { const node = document.querySelector('#toast'); node.textContent = message; node.classList.add('visible'); clearTimeout(toast.timer); toast.timer = setTimeout(() => node.classList.remove('visible'), 4500); }
function commit(next) { if (storageError) { toast('O armazenamento está indisponível. Recarregue para tentar novamente.'); return false; } try { listRepository.save(next); lists = next; return true; } catch { toast('Não foi possível salvar. Verifique o espaço e as permissões do navegador.'); return false; } }
function updateList(updated) { return commit(lists.map(list => list.id === updated.id ? updated : list)); }
function go(path) { location.hash = path; }
function openModal(html) { if (modal.open) modal.close(); modal.innerHTML = `<div class="modal-head"><span class="eyebrow">maRKetlist</span><button class="icon-button" data-action="close" aria-label="Fechar">✕</button></div>${html}`; const heading = modal.querySelector('h2'); if (heading) { heading.id = 'modal-title'; modal.setAttribute('aria-labelledby', heading.id); } modal.showModal(); }
const back = (path, text) => `<a class="back" href="#${path}">${icon('back')}${text}</a>`;
function photo(src, alt, className = '') { return `<span class="photo-frame ${className}"><img src="${esc(src)}" alt="${esc(alt)}" loading="lazy"></span>`; }
document.addEventListener('error', event => {
  const image = event.target;
  if (image instanceof HTMLImageElement && image.parentElement?.classList.contains('photo-frame')) {
    image.parentElement.classList.add('photo-missing');
    image.alt = 'Foto ainda não adicionada';
  }
}, true);
function card(recipe) { return `<article class="recipe-card"><a href="#/recipes/${recipe.id}" class="recipe-picture" tabindex="-1" aria-hidden="true">${photo(recipe.image, recipe.name)}<span class="badge">${recipe.category}</span></a><div class="recipe-card-body"><div class="small muted">${recipe.difficulty}</div><h3><a href="#/recipes/${recipe.id}">${recipe.name}</a></h3><div class="metadata"><span>${icon('clock')}${recipe.prepTime} min</span><span>${icon('people')}${recipe.servings} ${recipe.servings === 1 ? 'porção' : 'porções'}</span></div><a href="#/recipes/${recipe.id}" class="recipe-link">Ver receita ${icon('arrow')}</a></div></article>`; }
function listCard(list) {
  const count = list.items.filter(item => item.purchased).length;
  const draft = list.status === 'DRAFT';
  return `<article class="list-card"><span class="list-symbol">${icon('list')}</span><div><h3>${esc(list.name)}</h3><p>${list.items.length} produtos${draft ? ' · Em preparação' : ' · ' + count + ' comprados'}</p>${draft ? '' : `<div class="progress"><span style="width:${list.items.length ? count / list.items.length * 100 : 0}%"></span></div>`}<div class="list-card-actions">${list.status === 'COMPLETED' ? '' : `<a class="secondary" href="#/lists/${esc(list.id)}/edit">${draft ? 'Continuar criando' : 'Editar lista'}</a>`}${draft ? '' : `<a class="primary" href="#/lists/${esc(list.id)}">Abrir lista ${icon('arrow')}</a>`}<button class="secondary danger" data-action="delete-list" data-id="${esc(list.id)}">${icon('trash')} Excluir lista</button></div></div></article>`;
}

function empty(title, description, button = '') { return `<div class="empty">${icon('list')}<h3>${title}</h3><p>${description}</p>${button}</div>`; }
function shell(content, section) {
  const nav = [['home','Início','/'],['list','Listas','/lists'],['recipes','Receitas','/recipes'],['history','Histórico','/history']].map(([key,label,path]) => `<a href="#${path}" ${section === key ? 'class="current" aria-current="page"' : ''}>${icon(key)}<span>${label}</span></a>`).join('');
  app.innerHTML = `<header class="topbar"><a href="#/" class="brand" aria-label="maRKetlist início"><img src="assets/logo.svg" alt="">ma<strong>RK</strong>etlist<span class="brand-dot">.</span></a><span class="tagline">Menos improviso. Mais sabor.</span><span class="local-label"><i></i> Salvo neste dispositivo</span></header><nav class="navigation" aria-label="Navegação principal">${nav}</nav><main id="main">${storageError ? '<div class="notice">Não foi possível ler suas listas neste navegador. Os dados existentes foram preservados. Recarregue a página para tentar novamente.</div>' : ''}${content}</main><footer>Feito para facilitar suas compras e inspirar sua cozinha.</footer>`;
  document.title = `maRKetlist — ${section === 'recipes' ? 'Receitas' : section === 'history' ? 'Histórico' : section === 'list' ? 'Minhas listas' : 'Sua cozinha começa aqui'}`;
}
function home() { shell(`<section class="hero"><div><span class="eyebrow">DA IDEIA À MESA</span><h1>Sua próxima delícia<br>começa com uma <em>lista.</em></h1><p>Organize as compras, descubra receitas e leve<br class="desktop"> só o que precisa para a sua cozinha.</p><div class="actions"><button class="primary" data-action="new-list">${icon('plus')} Criar uma lista</button><a href="#/recipes" class="text-button">Explorar receitas ${icon('arrow')}</a></div></div><div class="hero-art">${photo("img/macarrao-a-bolonhesa.jpg", "Macarrão à Bolonhesa")}<span class="floating-note">${icon('check')} Um pouco de planejamento.<br><strong>Muito mais sabor.</strong></span></div></section><section><div class="section-head"><div><span class="eyebrow">TUDO ORGANIZADO</span><h2>Suas listas de compras <span class="count">${active().length}</span></h2></div><a class="text-button" href="#/lists">Ver minhas listas ${icon('arrow')}</a></div><div class="list-grid">${active().slice(0, 2).map(listCard).join('') || `<button class="new-list-card" data-action="new-list"><span>${icon('plus')}</span><div><h3>O que está faltando em casa?</h3><p>Crie sua primeira lista de compras</p></div>${icon('arrow')}</button>`}</div></section><section><div class="section-head"><div><span class="eyebrow">UMA PITADA DE INSPIRAÇÃO</span><h2>O que vamos cozinhar hoje?</h2><p>Você escolhe a receita. A gente ajuda com a lista.</p></div><a class="text-button" href="#/recipes">Ver todas as receitas ${icon('arrow')}</a></div><div class="recipe-grid">${recipes.slice(0,4).map(card).join('')}</div>${recipeError ? '<p class="notice">Não foi possível carregar as receitas. Recarregue para tentar novamente.</p>' : ''}</section>`, 'home'); }
function recipesPage() { shell(`<div class="page-title"><span class="eyebrow">DO SEU JEITO, NO SEU TEMPO</span><h1>Receitas para o dia a dia<span class="accent">.</span></h1><p>Inspire-se, escolha os ingredientes e deixe a lista com a gente.</p></div><label class="search">${icon('search')}<input id="recipe-search" type="search" placeholder="Buscar receita..." aria-label="Buscar receita" value="${esc(query)}"></label><div class="filters" aria-label="Categorias">${['Todas', ...categories].map(cat => `<button data-category="${cat}" aria-pressed="${cat === category}" class="chip ${cat === category ? 'selected' : ''}">${cat}</button>`).join('')}</div><p id="recipe-count" class="muted small" aria-live="polite"></p><div class="recipe-grid" id="recipe-results"></div>`, 'recipes'); filterRecipes(); }
function filterRecipes() { const found = recipes.filter(recipe => recipe.name.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(query.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'')) && (category === 'Todas' || recipe.category === category)); document.querySelector('#recipe-count').textContent = `${found.length} ${found.length === 1 ? 'receita' : 'receitas'} para se inspirar`; document.querySelector('#recipe-results').innerHTML = found.map(card).join('') || empty(recipeError ? 'Receitas indisponíveis' : 'Nenhuma receita encontrada', recipeError ? 'Recarregue a página para tentar novamente.' : 'Tente outro nome ou escolha outra categoria.'); }
function recipePage(recipe) { shell(`${back('/recipes','Todas as receitas')}<article class="recipe-detail">${photo(recipe.image, recipe.name, "detail-image")}<div class="detail-intro"><span class="eyebrow">${recipe.category} · ${recipe.difficulty}</span><h1>${recipe.name}</h1><p>${recipe.description}</p><div class="metadata large"><span>${icon('clock')}${recipe.prepTime} minutos</span><span>${icon('people')}${recipe.servings} ${recipe.servings === 1 ? 'porção' : 'porções'}</span></div><button class="primary" data-action="ingredients" data-id="${recipe.id}">${icon('plus')} Adicionar ingredientes à lista</button><p class="small muted">Escolha apenas o que você ainda não tem em casa.</p></div></article><div class="recipe-content"><section class="ingredients-panel"><div class="section-head"><h2>Ingredientes</h2><span class="count">${recipe.ingredients.length}</span></div><div class="selection-actions"><button data-action="select-all">Selecionar todos</button><button data-action="clear-selection">Limpar seleção</button></div>${recipe.ingredients.map(ingredient => `<label class="ingredient"><input type="checkbox" name="ingredient" value="${ingredient.id}" ${ingredient.optional ? '' : 'checked'}><span><strong>${esc(ingredient.name)}</strong><small>${qty(ingredient)}${ingredient.optional ? ' · opcional' : ''}</small></span></label>`).join('')}<button class="primary full" data-action="ingredients" data-id="${recipe.id}">${icon('plus')} Adicionar à lista</button></section><section class="instructions"><span class="eyebrow">MÃOS À OBRA</span><h2>Modo de preparo</h2><ol>${recipe.instructions.map(step => `<li>${esc(step)}</li>`).join('')}</ol></section></div>`, 'recipes'); }
function listsPage(history = false) { const drafts = lists.filter(list => list.status === 'DRAFT'); const found = lists.filter(list => list.status === (history ? 'COMPLETED' : 'ACTIVE')); shell(`<div class="section-head page-title"><div><span class="eyebrow">${history ? 'COMPRAS CONCLUÍDAS' : 'UM LUGAR PARA CADA COMPRA'}</span><h1>${history ? 'Histórico' : 'Minhas listas'}<span class="accent">.</span></h1><p>${history ? 'Suas compras anteriores, sempre por perto.' : 'Tudo o que você precisa, sem esquecer de nada.'}</p></div>${history ? '' : `<button class="primary" data-action="new-list">${icon('plus')} Nova lista</button>`}</div><div class="list-grid">${found.map(listCard).join('')}</div>${found.length ? '' : empty(history ? 'Nenhuma compra concluída ainda' : 'Sua próxima compra começa aqui', history ? 'Finalize uma lista para encontrá-la aqui.' : 'Crie uma lista ou escolha uma receita para começar.', history ? '<a class="text-button" href="#/lists">Ver minhas listas</a>' : '<button class="primary" data-action="new-list">Criar uma lista</button>')}${!history && drafts.length ? `<section class="drafts-section"><h2>Em preparação</h2><p>Continue adicionando produtos e confirme em Criar lista.</p><div class="list-grid">${drafts.map(listCard).join('')}</div></section>` : ''}`, history ? 'history' : 'list'); }
function listPage(list, editing = false) { const done = list.items.filter(item => item.purchased).length; shell(`${back(list.status === 'COMPLETED' ? '/history' : '/lists','Minhas listas')}<div class="section-head page-title"><div><span class="eyebrow">${editing ? (list.status === 'DRAFT' ? 'PREPARE SUA LISTA' : 'EDITAR LISTA') : (list.status === 'ACTIVE' ? 'SUA LISTA DE COMPRAS' : 'COMPRA CONCLUÍDA')}</span><h1>${esc(list.name)}</h1><p>${list.items.length} produtos${editing ? " · Adicione ou remova produtos" : " · " + done + " comprados"}</p></div>${editing ? '' : `<button class="secondary" data-action="share" data-id="${esc(list.id)}">${icon('share')} Compartilhar lista</button>`}</div><div class="shopping-layout ${editing ? '' : 'shopping-mode'}"><section class="shopping-panel">${editing ? '' : `<div class="progress"><span style="width:${list.items.length ? done / list.items.length * 100 : 0}%"></span></div>`}${editing ? `<form id="item-form" data-id="${esc(list.id)}" class="item-form"><label class="wide">Produto<input name="name" placeholder="O que está faltando?" maxlength="100" required></label><div><label for="item-quantity">Quantidade</label><div class="quantity-control"><input id="item-quantity" name="quantity" type="number" min="0.001" max="1000000" step="any" value="1" required><span class="quantity-arrows"><button type="button" data-quantity-step="1" aria-label="Aumentar quantidade em 1">▲</button><button type="button" data-quantity-step="-1" aria-label="Diminuir quantidade em 1">▼</button></span></div></div><label>Unidade<select name="unit">${['unidade','g','kg','ml','l','dente','folha','pitada','colher de sopa','colher de chá'].map(unit => `<option>${unit}</option>`).join('')}</select></label><label>Categoria<select name="category">${productCategories.map(cat => `<option>${cat}</option>`).join('')}</select></label><button class="primary" type="submit">${icon('plus')} Adicionar</button></form>` : ''}<div class="shopping-items">${list.items.map(item => `<div class="shopping-item ${!editing && item.purchased ? 'purchased' : ''}"><label>${editing ? '' : `<input type="checkbox" data-item="${esc(item.id)}" data-list="${esc(list.id)}" ${item.purchased ? 'checked' : ''} ${list.status !== 'ACTIVE' ? 'disabled' : ''}>`}<span><strong>${esc(item.name)}</strong><small>${qty(item)} · ${esc(item.category)}</small></span></label>${editing ? `<button class="icon-button" data-action="remove-item" data-id="${esc(list.id)}" data-item="${esc(item.id)}" aria-label="Remover ${esc(item.name)}">${icon('trash')}</button>` : ''}</div>`).join('') || empty('Sua lista está prontinha para começar', editing ? 'Adicione os produtos acima e confirme quando terminar.' : 'Esta lista não possui produtos.')}</div>${editing ? `<button class="primary full" data-action="save-list" data-id="${esc(list.id)}">${icon('check')} ${list.status === 'DRAFT' ? 'Criar lista' : 'Salvar alterações'}</button>` : ''}${!editing && list.status === 'ACTIVE' && list.items.length ? `<button class="secondary full" data-action="complete" data-id="${esc(list.id)}">${icon('check')} Concluir lista</button>` : ''}</section>${editing ? `<aside class="tip-card">${icon('recipes')}<h2>Uma receita.<br>Uma lista pronta.</h2><p>Encontre uma ideia gostosa e adicione só os ingredientes que faltam.</p><a href="#/recipes" class="text-button">Explorar receitas ${icon('arrow')}</a></aside>` : ''}</div>`, 'list'); }
function sharePreview(encoded) { try { const payload = localShareService.decode(encoded); shell(`<div class="share-preview">${icon('share')}<span class="eyebrow">UMA BOA IDEIA SE COMPARTILHA</span><h2>${payload.owner ? esc(payload.owner) : 'Alguém'} compartilhou uma lista</h2><h1>${esc(payload.list.name)}</h1><p>${payload.list.items.length} produtos</p><ul>${payload.list.items.map(item => `<li><strong>${esc(item.name)}</strong><span>${qty(item)}</span></li>`).join('')}</ul><p class="notice">Você terá sua própria cópia. Alterações não serão sincronizadas com a lista original.</p><button class="primary full" data-action="import">${icon('plus')} Adicionar às minhas listas</button></div>`, 'list'); } catch (error) { shell(empty('Este link não pôde ser aberto', esc(error.message), '<a href="#/" class="primary">Voltar ao início</a>'), 'list'); } }
function render() { if (modal.open) modal.close(); const path = location.hash.slice(1) || '/'; if (path.startsWith('/share/')) return sharePreview(path.slice(7)); const parts = path.split('/').filter(Boolean); if (parts[0] === 'recipes' && parts[1]) { const recipe = recipes.find(r => r.id === parts[1]); if (recipe) return recipePage(recipe); } else if (parts[0] === 'recipes') return recipesPage(); else if (parts[0] === 'lists' && parts[1]) { const list = lists.find(l => l.id === parts[1]); if (list) return listPage(list, list.status === 'DRAFT' || (parts[2] === 'edit' && list.status === 'ACTIVE'));  } else if (parts[0] === 'lists') return listsPage(); else if (parts[0] === 'history') return listsPage(true); else if (!parts.length) return home(); shell(empty('Página não encontrada','Esta receita ou lista não está disponível.', '<a class="primary" href="#/">Voltar ao início</a>'), 'home'); }
function newListDialog() { openModal('<h2>Uma nova lista</h2><p class="muted">Dê um nome para a sua próxima compra.</p><form id="new-list-form"><label>Nome da lista<input name="name" maxlength="100" placeholder="Ex.: Compras da semana" required autofocus></label><button class="primary full">Adicionar produtos</button></form>'); }
let pendingIngredients = null;
function ingredientDialog(recipeId) { const recipe = recipes.find(r => r.id === recipeId); const selected = [...document.querySelectorAll('input[name="ingredient"]:checked')].map(input => input.value); const ingredients = recipe.ingredients.filter(item => selected.includes(item.id)); if (!ingredients.length) return toast('Selecione pelo menos um ingrediente.'); pendingIngredients = { ingredients }; openModal(`<h2>Adicionar em qual lista?</h2><p class="muted">${ingredients.length} ingredientes selecionados. Quase na mesa!</p><form id="destination-form">${active().map((list, index) => `<label class="destination"><input type="radio" name="destination" value="${esc(list.id)}" ${index === 0 ? 'checked' : ''}>${esc(list.name)}</label>`).join('')}<label class="destination"><input type="radio" name="destination" value="new" ${!active().length ? 'checked' : ''}>Criar nova lista</label><label id="new-destination-label" ${active().length ? 'hidden' : ''}>Nome da nova lista<input name="newName" maxlength="100" value="${esc(recipe.name)}" ${!active().length ? 'required' : ''}></label><button class="primary full">Adicionar ingredientes</button></form>`); }
function finishIngredients(choices = {}) { const { list, ingredients, isNew } = pendingIngredients; const updated = addIngredients(list, ingredients, choices); if (isNew) updated.status = 'DRAFT'; const success = isNew ? commit([...lists, updated]) : updateList(updated); if (success) { modal.close(); pendingIngredients = null; go(`/lists/${updated.id}/edit`); toast('Ingredientes adicionados à sua lista.'); } }
function destinationSubmit(form) { const data = new FormData(form); const destination = data.get('destination'); const isNew = destination === 'new'; const name = String(data.get('newName') || '').trim(); if (isNew && !name) return toast('Dê um nome para a nova lista.'); const list = isNew ? newList(name) : active().find(l => l.id === destination); if (!list) return toast('Escolha uma lista ativa.'); pendingIngredients = { ...pendingIngredients, list, isNew }; const duplicates = pendingIngredients.ingredients.filter(item => list.items.some(other => sameProduct(item, other))); if (!duplicates.length) return finishIngredients(); openModal(`<h2>Alguns produtos já estão na lista</h2><p class="muted">Escolha o que fazer com cada ingrediente.</p><form id="duplicates-form">${duplicates.map(item => { const compatible = list.items.some(other => sameProduct(item, other) && compatibleUnits(item, other)); return `<fieldset><legend>${esc(item.name)} já está na sua lista.</legend><p class="small muted">Adicionar: ${qty(item)}${compatible ? '' : ' · Unidades diferentes: não é possível somar.'}</p><select aria-label="Como adicionar ${esc(item.name)}" name="${esc(item.id)}">${compatible ? '<option value="sum">Somar quantidade</option>' : ''}<option value="add">Adicionar mesmo assim</option><option value="skip">Ignorar</option></select></fieldset>`; }).join('')}<button class="primary full">Adicionar ingredientes</button></form>`); }
async function copyLink(url) { try { if (!navigator.clipboard?.writeText) throw new Error(); await navigator.clipboard.writeText(url); toast('Link copiado!'); } catch { const input = modal.querySelector('#share-url'); input.focus(); input.select(); toast('Selecione e copie o link acima.'); } }
function shareDialog(list) { let encoded; try { encoded = localShareService.encode(list); } catch (error) { return toast(error.message); } const url = new URL(location.href); url.hash = `/share/${encoded}`; openModal(`<h2>Compartilhar lista</h2><p class="muted">${esc(list.name)} · ${list.items.length} produtos</p><p class="notice">Quem receber o link poderá ver os produtos e salvar uma cópia. Cada pessoa terá sua própria lista, sem sincronização.</p><label>Seu nome (opcional)<input id="share-owner" maxlength="60" placeholder="Ex.: João"></label><label>Link da lista<input id="share-url" readonly value="${esc(url.href)}"></label><div class="actions">${navigator.share ? `<button class="primary" id="native-share">${icon('share')} Compartilhar lista</button>` : ''}<button class="secondary" id="copy-share">Copiar link</button></div>`); modal.querySelector('#share-owner').addEventListener('input', event => { try { url.hash = `/share/${localShareService.encode(list, event.target.value.trim())}`; modal.querySelector('#share-url').value = url.href; } catch (error) { toast(error.message); } }); modal.querySelector('#copy-share').onclick = () => copyLink(url.href); const shareButton = modal.querySelector('#native-share'); if (shareButton) shareButton.onclick = async () => { try { await navigator.share({ title: `maRKetlist — ${list.name}`, text: 'Uma lista de compras para você', url: url.href }); } catch (error) { if (error.name !== 'AbortError') toast('Não foi possível compartilhar. Use Copiar link.'); } }; }
function changeQuantity(direction) {
  const input = document.querySelector('#item-quantity');
  if (input) input.value = String(stepQuantity(input.valueAsNumber, direction));
}
document.addEventListener('keydown', event => {
  if (event.target.id === 'item-quantity' && ['ArrowUp', 'ArrowDown'].includes(event.key)) {
    event.preventDefault(); changeQuantity(event.key === 'ArrowUp' ? 1 : -1);
  }
});
document.addEventListener('click', event => {
  const quantityButton = event.target.closest('[data-quantity-step]');
  if (quantityButton) { changeQuantity(Number(quantityButton.dataset.quantityStep)); return; }

  const filter = event.target.closest('[data-category]'); if (filter) { category = filter.dataset.category; document.querySelectorAll('[data-category]').forEach(button => { button.classList.toggle('selected', button === filter); button.setAttribute('aria-pressed', String(button === filter)); }); filterRecipes(); return; }
  const button = event.target.closest('[data-action]'); if (!button) return; const action = button.dataset.action; const list = lists.find(l => l.id === button.dataset.id);
  if (action === 'close') modal.close();
  else if (action === 'new-list') newListDialog();
  else if (action === 'ingredients') ingredientDialog(button.dataset.id);
  else if (action === 'select-all' || action === 'clear-selection') document.querySelectorAll('[name="ingredient"]').forEach(input => input.checked = action === 'select-all');
  else if (action === 'share' && list) shareDialog(list);
  else if (action === 'delete-list' && list) {
    openModal(`<h2>Excluir lista?</h2><p>A lista <strong>${esc(list.name)}</strong> e todos os seus produtos serão excluídos deste dispositivo. Essa ação não pode ser desfeita.</p><div class="actions"><button class="secondary" data-action="close">Cancelar</button><button class="primary danger-confirm" data-action="confirm-delete-list" data-id="${esc(list.id)}">${icon('trash')} Excluir lista</button></div>`);
    modal.querySelector('[data-action="close"]:not(.icon-button)').focus();
  }
  else if (action === 'confirm-delete-list' && list) {
    if (commit(lists.filter(saved => saved.id !== list.id))) {
      modal.close(); render(); toast('Lista excluída.');
    }
  }
  else if (action === 'save-list' && list && ['DRAFT', 'ACTIVE'].includes(list.status)) { if (updateList({ ...list, status: 'ACTIVE' })) { go('/lists'); toast(list.status === 'DRAFT' ? 'Lista criada!' : 'Alterações salvas.'); } }
  else if (action === 'remove-item' && list && ['DRAFT', 'ACTIVE'].includes(list.status)) { if (updateList({ ...list, items: list.items.filter(item => item.id !== button.dataset.item) })) listPage(lists.find(l => l.id === list.id), true); }
  else if (action === 'complete' && list?.status === 'ACTIVE') openModal(`<h2>Concluir esta lista?</h2><p>${list.items.filter(item => !item.purchased).length ? 'Ainda há produtos não marcados. Eles manterão esse estado no histórico.' : 'Sua lista ficará disponível no histórico.'}</p><button class="primary full" data-action="confirm-complete" data-id="${esc(list.id)}">Concluir lista</button>`);
  else if (action === 'confirm-complete' && list?.status === 'ACTIVE') { if (updateList({ ...list, status: 'COMPLETED', completedAt: new Date().toISOString() })) { modal.close(); go('/history'); toast('Compra salva no histórico.'); } }
  else if (action === 'import') { try { const imported = localShareService.import(localShareService.decode(location.hash.slice('#/share/'.length))); if (commit([...lists, imported])) { location.replace(`#/lists/${imported.id}`); toast('Sua cópia foi adicionada às listas.'); } } catch (error) { toast(error.message); } }
});
document.addEventListener('input', event => { if (event.target.id === 'recipe-search') { query = event.target.value; filterRecipes(); } });
document.addEventListener('change', event => {
  const input = event.target;
  if (input.name === 'destination') { const label = document.querySelector('#new-destination-label'); label.hidden = input.value !== 'new'; label.querySelector('input').required = input.value === 'new'; }
  if (input.dataset.item && input.dataset.list) { const list = lists.find(l => l.id === input.dataset.list); if (!list || list.status !== 'ACTIVE') return; if (updateList({ ...list, items: list.items.map(item => item.id === input.dataset.item ? { ...item, purchased: input.checked } : item) })) { const row = input.closest('.shopping-item'); row.classList.toggle('purchased', input.checked); const updated = lists.find(l => l.id === list.id); document.querySelector('.page-title p').textContent = `${updated.items.length} produtos · ${updated.items.filter(i => i.purchased).length} comprados`; document.querySelector('.shopping-panel .progress span').style.width = `${updated.items.filter(i => i.purchased).length / updated.items.length * 100}%`; } else input.checked = !input.checked; }
});
document.addEventListener('submit', event => {
  event.preventDefault(); const form = event.target; const data = new FormData(form);
  if (form.id === 'new-list-form') { const name = String(data.get('name')).trim(); if (!name) return toast('Digite o nome da lista.'); const list = { ...newList(name), status: 'DRAFT' }; if (commit([...lists, list])) { modal.close(); go(`/lists/${list.id}/edit`); } }
  else if (form.id === 'destination-form') destinationSubmit(form);
  else if (form.id === 'duplicates-form') finishIngredients(Object.fromEntries(data));
  else if (form.id === 'item-form') { const name = String(data.get('name')).trim(); if (!name) return toast('Digite o nome do produto.'); const list = lists.find(l => l.id === form.dataset.id); if (!list || !['DRAFT', 'ACTIVE'].includes(list.status)) return; const item = { id: id(), name, quantity: Number(data.get('quantity')), unit: data.get('unit'), category: data.get('category'), purchased: false }; if (!Number.isFinite(item.quantity) || item.quantity <= 0 || item.quantity > 1000000) return toast('Digite uma quantidade válida.'); if (updateList({ ...list, items: [...list.items, item] })) { listPage(lists.find(l => l.id === list.id), true); document.querySelector('#item-form input').focus(); } }
});
window.addEventListener('hashchange', () => { render(); window.scrollTo(0,0); });
window.addEventListener('storage', event => { if (event.key === 'marketlist.lists.v1') { try { lists = listRepository.load(); storageError = false; render(); toast('Listas atualizadas neste dispositivo.'); } catch { storageError = true; render(); } } });
try { lists = listRepository.load(); } catch { storageError = true; }
try { recipes = await recipeRepository.load(); } catch { recipeError = true; }
render();

